/* AuthSchoolMapMapper.upsertAuthSchoolMap */
INSERT INTO auth_school_map (
    user_no, school_code, granted_by, status, created_by, updated_by, created_at, updated_at
)
VALUES (
    #{userNo}, #{schoolCode}, #{grantedBy}, #{status}, #{createdBy}, #{updatedBy}, #{createdAt}, #{updatedAt}
)
ON DUPLICATE KEY UPDATE
    granted_by = VALUES(granted_by),
    status = VALUES(status),
    updated_by = VALUES(updated_by),
    updated_at = VALUES(updated_at)

mapper.update:
/* AuthSchoolMapMapper.revokeByUserNoAndSchoolCode */
UPDATE auth_school_map
SET status = 'REVOKED',
    updated_by = #{updatedBy},
    updated_at = NOW()
WHERE user_no = #{userNo}
  AND school_code = #{schoolCode}
  AND status = 'ACTIVE'
